oast-bg: var(--tint);\n  --toast-text: #ffffff;\n  --shadow-soft: rgba(0, 0, 0, 0);\n  --chip-r: 999px;\n}\n:root[data-skin=\"ink\"]:not(.theme--dark) {\n  --bg: #ffffff;\n  --bg-elev: #f7f9f9;\n  --surface: #ffffff;\n  --surface-press: #f7f9f9;\n  --sep: #eff3f4;\n  --sep-strong: #cfd9de;\n  --text: #0f1419;\n  --text-2: #536471;\n  --text-3: #8b98a5;\n  --bar: rgba(255, 255, 255, 0.85);\n  --bar-line: #eff3f4;\n  color-scheme: light;\n  --shadow-soft: rgba(0, 0, 0, 0.08);\n}\n:root[data-skin=\"ink\"] .list { border-left: 0; border-right: 0; border-radius: 0; margin: 0; }\n:root[data-skin=\"ink\"] .card__author,\n:root[data-skin=\"ink\"] .reply__author { color: var(--text); font-weight: 700; }\n:root[data-skin=\"ink\"] .card__title { font-weight: 700; }\n:root[data-skin=\"ink\"] .btn { border-radius: 999px; font-weight: 700; }\n:root[data-skin=\"ink\"] .btn--filled,\n:root[data-skin=\"ink\"] .btn:active { background: var(--tint); color: var(--on-tint); border-color: var(--tint); }\n:root[data-skin=\"ink\"] .segmented { border-radius: 999px; }\n:root[data-skin=\"ink\"] .hero__title { font-weight: 800; font-size: 30px; letter-spacing: -0.02em; }\n:root[data-skin=\"ink\"] .tab-bar__item--active { color: var(--text); }\n:root[data-skin=\"ink\"] .tab-bar__item--active .tab-bar__icon { stroke-width: 2.4; }\n:root[data-skin=\"ink\"] { --group-r: 0; }\n\n/* Элементы интерфейса (модальное окно, уведомление, выноска) — оформление темы. */\n:root[data-skin=\"ink\"] { --modal-r: 2px; --modal-bg: var(--surface); --modal-border: 1px solid var(--sep-strong); --modal-shadow: 4px 4px 0 var(--sep-strong); --modal-head-border: 1px solid var(--sep-strong); --overlay: rgba(0, 0, 0, 0.3); --toast-r: 2px; --callout-r: 2px; }\n/* Бумага: смещённая тень вместо размытой, заголовок шрифтом темы. */\n:root[data-skin=\"ink\"] .modal__title { font-size: 19px; font-weight: 600; }\n"},"lounge":{"meta":{"id":"lounge","name":"Lounge","mode":"dark","accent":"#5865f2","barsLight":["#f2f3f5",1.0,"#fff